#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    vector<array<long long, 3>> ops(q);
    for (auto &op : ops) cin >> op[0] >> op[1] >> op[2];
    // Walk the operations backwards: the first point assignment met is the last one applied,
    // and floor holds the largest global lower bound applied after it.
    long long floor = 0;
    vector<long long> last(n, -1);
    for (int i = q - 1; i >= 0; i--) {
        auto [t, x, v] = ops[i];
        if (t == 2) floor = max(floor, x);
        else if (last[x - 1] < 0) last[x - 1] = max(v, floor);
    }
    string out;
    for (int i = 0; i < n; i++) {
        if (i) out += ' ';
        out += to_string(last[i] < 0 ? max(a[i], floor) : last[i]);
    }
    cout << out << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[][] ops = new long[q][3];
        for (int i = 0; i < q; i++)
            for (int j = 0; j < 3; j++) ops[i][j] = nextLong();
        long floor = 0;
        long[] last = new long[n];
        Arrays.fill(last, -1);
        for (int i = q - 1; i >= 0; i--) {
            long t = ops[i][0], x = ops[i][1], v = ops[i][2];
            if (t == 2) floor = Math.max(floor, x);
            else if (last[(int) x - 1] < 0) last[(int) x - 1] = Math.max(v, floor);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(last[i] < 0 ? Math.max(a[i], floor) : last[i]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	ops := make([][3]int, q)
	for i := range ops {
		ops[i] = [3]int{nextInt(), nextInt(), nextInt()}
	}
	floor := 0
	last := make([]int, n)
	for i := range last {
		last[i] = -1
	}
	for i := q - 1; i >= 0; i-- {
		t, x, v := ops[i][0], ops[i][1], ops[i][2]
		if t == 2 {
			floor = max(floor, x)
		} else if last[x-1] < 0 {
			last[x-1] = max(v, floor)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		if i > 0 {
			w.WriteByte(' ')
		}
		if last[i] < 0 {
			w.WriteString(strconv.Itoa(max(a[i], floor)))
		} else {
			w.WriteString(strconv.Itoa(last[i]))
		}
	}
	w.WriteByte('\n')
}
